      NVQ_4_5_ticked <- rowSums(data %>% safe_select(., NVQ_4_5_cols) == 1) > 0

      # NVQ 1-3 qualifications
      NVQ_1_3_cols <- c("W9ACQUC0F", "W9ACQUC0G", "W9ACQUC0H", "W9ACQUC0I", "W9VCQUC0B", "W9VCQUC0D", "W9VCQUC0E", "W9VCQUC0F")
      NVQ_1_3_ticked <- rowSums(data %>% safe_select(., NVQ_1_3_cols) == 1) > 0

      # Entry level qualifications
      entry_level_cols <- c("W9VCQUC0F", "W9VCQUC0K", "W9VCQUC0Q")
      entry_level_ticked <- rowSums(data %>% safe_select(., entry_level_cols) == 1) > 0

      # Other qualifications
