      other_ticked <- rowSums(data %>% safe_select(., other_cols) == 1) > 0

      # None of these qualifications
      none_of_these_ticked <- if ("W9ACQUC0S" %in% names(data)) data$W9ACQUC0S == 1 else FALSE
    }

